## solution

#### dynamic programming with memoization

```cpp
#include <math.h>
#include <unordered_map>

int summingSquares(int n, std::unordered_map<int, int> &memo) {
  if (memo.count(n) > 0) {
    return memo[n];
  }

  if (n == 0) {
    return 0;
  }

  int min = 0;

  for (int num = 1; num <= std::sqrt(n); num += 1) {
    int remainder = n - (num * num);
    int squares = 1 + summingSquares(remainder, memo);
    if (min == 0 || squares < min) {
      min = squares;
    }
  }

  memo[n] = min;
  return min;
}

int summingSquares(int n) {
  std::unordered_map<int, int> memo;
  return summingSquares(n, memo);
}
```

- n = length of nums
- Time: O(n * sqrt(n))
- Space: O(n)
